import dev.hua.ptcglive.engine.*;
import dev.hua.ptcglive.engine.effect.*;
import dev.hua.ptcglive.engine.field.*;
import dev.hua.ptcglive.rules.*;
import java.util.*;

/** Cross-choice success counts belong to one resolution and are written only after the physical action succeeds. */
public final class StarterDeck100IfDoTest {
    static final UUID A=StarterDeck100PokemonTest.A,B=StarterDeck100PokemonTest.B;
    static final String GRASS="sd100_cn_grass_energy",WATER="sd100_cn_water_energy",PSYCHIC="sd100_cn_psychic_energy";
    static String id(int n){return StarterDeck100PokemonTest.id(n);}
    static void check(boolean b,String s){StarterDeck100PokemonTest.check(b,s);}
    static CardInstance hand(ServerMatch m,String id){return StarterDeck100PokemonTest.hand(m,id);}
    static void discard(ServerMatch m,String id){var c=hand(m,id);m.discardHandCardsByEffect(A,A,List.of(c.instanceId()));}
    static void select(ServerMatch m,int n){StarterDeck100PokemonTest.select(m,n);}
    static void target(ServerMatch m,UUID id){StarterDeck100PokemonTest.choosePokemon(m,id);}
    static void shield(ServerMatch m,String source){var effect=EffectRegistry.standard().parse(com.google.gson.JsonParser.parseString("{\"type\":\"prevent_effects\",\"target\":\"OWN_ACTIVE\",\"source\":\""+source+"\",\"from\":\"OWN\",\"scope\":\"EFFECTS_ONLY\",\"duration\":\"LEAVES_PLAY\"}").getAsJsonObject());m.executeEffectProgramByRule(A,null,new EffectProgram(List.of(new TriggeredEffects(EffectTrigger.ON_CARD_PLAYED,List.of(),List.of(effect)))),EffectTrigger.ON_CARD_PLAYED);}
    public static void main(String[] args){aroma();raihan("NONE");raihan("CHECKUP");raihan("COUNTERS");raihan("ATTACK");melony(false);melony(true);houndoom(0);houndoom(1);underworld(0);underworld(1);malformed();System.out.println("StarterDeck100IfDoTest passed: successful-action counts, KO eligibility, failed/prevented attachment, draw exhaustion, typed/family targets and nested continuations");}
    static void aroma(){for(int available:List.of(0,1,2)){var m=StarterDeck100CommonTest.game(387,1);m.applySpecialConditionByEffect(A,A,SpecialCondition.POISONED);var c=hand(m,id(387));int remove=m.privateView(A).deck().size()-available;if(remove>0)m.drawCardsByEffect(A,A,remove);int before=m.privateView(A).hand().size();if(available==0){check(!m.canPlayTrainer(A,c.instanceId(),null),"Aroma cured without drawing any card");continue;}m.playTrainer(A,c.instanceId(),null);check(m.privateView(A).hand().size()==before-1+available&&m.activePokemonView(A).conditions().isEmpty(),"Aroma did not cure after actual partial/full draw");}}
    static void raihan(String cause){var m=StarterDeck100CommonTest.game(391,1);var c=hand(m,id(391));UUID host=m.activePokemonView(A).pokemonId();if(!cause.equals("NONE"))m.placeDamageCountersByEffect(A,A,host,m.activePokemonView(A).hitPoints()/10-1);if(cause.equals("ATTACK")){StarterDeck100EnergyTest.attach(m,A,B,GRASS,m.activePokemonView(B).pokemonId());StarterDeck100EnergyTest.attach(m,A,B,GRASS,m.activePokemonView(B).pokemonId());}m.endTurn(A);
        switch(cause){case "COUNTERS"->{m.placeDamageCountersByEffect(B,A,host,1);StarterDeck100CombatTest.settleKnockouts(m);m.endTurn(B);}case "ATTACK"->{m.attack(B,"leaf-drain");StarterDeck100CombatTest.settleKnockouts(m);}case "CHECKUP"->{m.applySpecialConditionByEffect(B,A,SpecialCondition.POISONED);m.endTurn(B);StarterDeck100CombatTest.settleKnockouts(m);}default->m.endTurn(B);}
        boolean eligible=Set.of("COUNTERS","ATTACK").contains(cause);check(!m.canPlayTrainer(A,c.instanceId(),null),"Raihan played without discarded Basic Energy");discard(m,GRASS);check(m.canPlayTrainer(A,c.instanceId(),null)==eligible,"Raihan last-opponent-turn eligibility: "+cause);if(!eligible)return;
        m.playTrainer(A,c.instanceId(),null);select(m,1);check(m.hasPendingEffectChoice(),"Raihan completed before target choice");var p=m.effectAttachmentPrompt(A);m.chooseEffectAttachmentTarget(A,p.resolutionId(),p.step(),m.activePokemonView(A).pokemonId());var search=m.effectCardPrompt(A);check(search.minimum()==1&&search.maximum()==1&&m.effectCardReveal()==null,"Raihan search not mandatory private unrestricted choice");select(m,1);check(m.activePokemonView(A).attachedEnergyIds().size()==1&&!m.hasPendingEffectChoice(),"Raihan attachment/search sequence incomplete");
    }
    static void melony(boolean prevented){var m=StarterDeck100CommonTest.game(409,1,WATER,id(13));var c=hand(m,id(409));check(!m.canPlayTrainer(A,c.instanceId(),null),"Melony drew without Water Energy");discard(m,WATER);var nonV=hand(m,id(13));m.playBasicPokemonToBench(A,nonV.instanceId());if(prevented)shield(m,"TRAINER");int before=m.privateView(A).hand().size();m.playTrainer(A,c.instanceId(),null);var p=m.effectPokemonPrompt(A);check(p.targets().stream().noneMatch(t->t.pokemonId().equals(PokemonIdentityTestSupport.logical(m,A,nonV.instanceId()))),"Melony offered non-V host");TopDeckLookTest.rejects(()->m.chooseEffectPokemon(A,p.resolutionId(),p.step(),PokemonIdentityTestSupport.logical(m,A,nonV.instanceId())));target(m,m.activePokemonView(A).pokemonId());select(m,1);check(m.privateView(A).hand().size()==before-1+(prevented?0:3),"Melony did not use the actual attachment result");check(m.activePokemonView(A).attachedEnergyIds().size()==(prevented?0:1),"Melony attachment protection failed");}
    static void houndoom(int count){var m=StarterDeck100PokemonTest.game(262,id(412),id(1));var outsider=hand(m,id(1));m.playBasicPokemonToBench(A,outsider.instanceId());UUID host=m.activePokemonView(A).pokemonId();StarterDeck100PokemonTest.ability(m,host);var p=m.effectPokemonPrompt(A);check(p.targets().stream().noneMatch(t->t.pokemonId().equals(PokemonIdentityTestSupport.logical(m,A,outsider.instanceId()))),"Roar offered non-Single-Strike Pokemon");target(m,host);var cards=m.effectCardPrompt(A);check(cards.candidates().stream().allMatch(c->c.definitionId().equals(id(412))),"Roar offered wrong Energy identity");select(m,count);check(m.activePokemonView(A).attachedEnergyIds().size()==count&&m.activePokemonView(A).damage()==count*20,"Roar damaged host after failed search or missed successful attachment");check(!m.canUseAbility(A,host,"single-strike-roar"),"Roar once-per-source limit lost");StarterDeck100PokemonTest.attack(m,0);check(m.lastAttack().finalDamage()==50+20*count,"Roar Energy did not affect Darkness Fang");}
    static void underworld(int count){var m=StarterDeck100PokemonTest.game(204,PSYCHIC,id(1));hand(m,PSYCHIC);var outsider=hand(m,id(1));m.playBasicPokemonToBench(A,outsider.instanceId());int before=m.privateView(A).hand().size();UUID source=m.activePokemonView(A).pokemonId(),bench=m.benchPokemonView(A).stream().filter(v->!v.pokemonId().equals(PokemonIdentityTestSupport.logical(m,A,outsider.instanceId()))).findFirst().orElseThrow().pokemonId();StarterDeck100PokemonTest.ability(m,source);var p=m.effectPokemonPrompt(A);check(p.targets().stream().noneMatch(t->t.pokemonId().equals(source)||t.pokemonId().equals(PokemonIdentityTestSupport.logical(m,A,outsider.instanceId()))),"Underworld Door offered Active or non-Psychic");target(m,bench);select(m,count);check(m.privateView(A).hand().size()==before+count,"Underworld Door draw did not depend on actual hand attachment");StarterDeck100EnergyTest.attach(m,A,A,PSYCHIC,source);StarterDeck100PokemonTest.attack(m,0);check(m.lastAttack().finalDamage()==40+30*count,"Max Geist failed to count whole-field Psychic units");}
    static void malformed(){for(String effects:List.of("{\"type\":\"draw\",\"amount\":1,\"conditions\":[{\"type\":\"BOUND_COUNT\",\"bind\":\"future\",\"value\":1}]}","{\"type\":\"draw\",\"amount\":1,\"bind\":\"same\"},{\"type\":\"draw\",\"amount\":1,\"bind\":\"same\"}"))TopDeckLookTest.rejects(()->TrainerProgramRules.validate(ComposedTrainerIntegrationTest.item(effects).effectProgram()));}
}
